// AI Agent output JSON parser with clean string evaluation & formatting
const raw = $json.output || $json.text || '';
let parsed = { subject: '', body: '' };
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (e) {
  // fallback
}

const leadItem = $('Loop Over Leads (Outreach)').item.json || {};
const leadName = leadItem.Name || leadItem.name || 'there';
const leadCompany = leadItem.Company || leadItem.company || 'your company';
const leadTitle = leadItem.Title || leadItem.title || leadItem.designation || 'Leader';
const leadLocation = leadItem.Location || leadItem.location || leadItem.country || 'India';

let subject = parsed.subject || `Quick question regarding ${leadCompany}'s web & AI stack`;
let body = parsed.body || raw || `Hi ${leadName},

I noticed your work as ${leadTitle} at ${leadCompany}.

At Technewity Labs, we help companies build modern, high-converting websites and custom AI automation workflows to streamline operations.

Would you be open to a quick 10-minute chat next week to see how we could support ${leadCompany}?

Best regards,
Technewity Team`;

// Clean any leftover raw expression strings
subject = subject
  .replace(/\{\{\s*\$json\.Company[^}]*\}\}/gi, leadCompany)
  .replace(/\{\{\s*\$json\.company[^}]*\}\}/gi, leadCompany)
  .replace(/\{\{\s*\$json\.Name[^}]*\}\}/gi, leadName)
  .replace(/\{\{\s*\$json\.name[^}]*\}\}/gi, leadName);

body = body
  .replace(/\{\{\s*\$json\.Company[^}]*\}\}/gi, leadCompany)
  .replace(/\{\{\s*\$json\.company[^}]*\}\}/gi, leadCompany)
  .replace(/\{\{\s*\$json\.Name[^}]*\}\}/gi, leadName)
  .replace(/\{\{\s*\$json\.name[^}]*\}\}/gi, leadName)
  .replace(/\{\{\s*\$json\.Title[^}]*\}\}/gi, leadTitle)
  .replace(/\{\{\s*\$json\.title[^}]*\}\}/gi, leadTitle)
  .replace(/\{\{\s*\$json\.designation[^}]*\}\}/gi, leadTitle)
  .replace(/\{\{\s*\$json\.Location[^}]*\}\}/gi, leadLocation)
  .replace(/\{\{\s*\$json\.location[^}]*\}\}/gi, leadLocation)
  .replace(/\{\{\s*\$json\.country[^}]*\}\}/gi, leadLocation);

const verifiedEmail = leadItem.Email || leadItem.email || '';

return [{
  json: {
    ...leadItem,
    email: verifiedEmail,
    Email: verifiedEmail,
    emailSubject: subject,
    emailBody: body,
    Status: 'Contacted'
  }
}];

